  const pts = [];
  for (let i = 0; i < 3; i++) {
    const a = Math.PI / 2 + (i * 2 * Math.PI) / 3;
    pts.push(new Vector2(R * Math.cos(a), R * Math.sin(a)));
  }
  return pts;
}

function subdivide(a, b) {
  const d = b.clone().sub(a);
  const third = d.clone().multiplyScalar(1 / 3);
  const p1 = a.clone().add(third);
  const p2 = p1.clone().add(third);
  const p3 = p2.clone().add(third);
  // rotate third by -60 degrees -> outward bump for CCW rings
  const peak = p1.clone().add(
    new Vector2(
