result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/koch.js", "content": "import { Vector2, Shape, ExtrudeGeometry, Mesh } from 'three';

const SIDE = 6;
const CIRCUMRADIUS = SIDE / Math.sqrt(3);

/**
 * Equilateral triangle (side 6) centered at the origin, counter-clockwise,
 * as the seed for the Koch construction.
 */
function initialTriangle() {
  const pts = [];
  for (let i = 0; i < 3; i++) {
    const angle = Math.PI / 2 + (i * 2 * Math.PI) / 3;
    pts.push(new Vector2(CIRCUMRADIUS * Math.cos(angle), CIRCUMRADIUS * Math.sin(angle)));
  }
  return pts;
}

/**
 * Koch substitution on a single edge [a, b]:
 *   a -- p1 -- peak -- p2 -- b
 * The middle third is replaced by two sides of an equilateral triangle
 * erected on the outward side of the edge (right of direction for CCW rings).
 * Returns all five points, including both parent endpoints.
 */
function subdivide(a, b) {
  const third = b.clone().sub(a).multiplyScalar(1 / 3);
  const p1 = a.clone().add(third);
  const p2 = p1.clone().add(third);
  const cos = Math.cos(-Math.PI / 3);
  const sin = Math.sin(-Math.PI / 3);
  const rotated = new Vector2(
    third.x * cos - third.y * sin,
    third.x * sin + third.y * cos
  );
  const peak = p1.clone().add(rotated);
  return [a.clone(), p1, peak, p2, b.clone()];
}

/**
 * Koch snowflake outline after `iterations` subdivision rounds.
 * Returns an open ring of Vector2 (no duplicated closing point):
 * its cyclic segment count is exactly 3 * 4^iterations.
 */
export function kochOutline(iterations) {
  let points = initialTriangle();
  for (let n = 0; n < iterations; n++) {
    const next = [];
    for (let i = 0; i < points.length; i++) {
      const a = points[i];
      const b = points[(i + 1) % points.length];
      const seg = subdivide(a, b);
      // push a, p1, peak, p2 — omit b, which starts the next edge
      next.push(seg[0], seg[1], seg[2], seg[3]);
    }
    points = next;
  }
  return points;
}

/**
 * Total perimeter of a closed polygon given as an open ring of points.
 */
export function perimeterOf(points) {
  let total = 0;
  for (let i = 0; i < points.length; i++) {
    total += points[i].distanceTo(points[(i + 1) % points.length]);
  }
  return total;
}

/**
 * Build the ornament mesh: the Koch outline as a THREE.Shape, extruded
 * straight along z by `depth` with beveling disabled.
 */
export function buildOrnament(iterations, depth = 0.5) {
  const outline = kochOutline(iterations);
  const shape = new Shape(outline);
  const geometry = new ExtrudeGeometry(shape, {
    depth,
    bevelEnabled: false,
    curveSegments: 1
  });
  return new Mesh(geometry);
}
"})
