result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/koch.test.js", "content": "import { describe, it, expect } from 'vitest';
import { Box3 } from 'three';
import { kochOutline, buildOrnament, perimeterOf } from '../src/koch.js';

describe('koch snowflake ornament', () => {
  it('has segment count 3 * 4^n for n = 0..3', () => {
    for (const n of [0, 1, 2, 3]) {
      expect(kochOutline(n).length).toBe(3 * 4 ** n);
    }
  });

  it('grows perimeter by exactly 4/3 per iteration (within 1e-9)', () => {
    const expected = 4 / 3;
    for (let n = 0; n < 3; n++) {
      const p0 = perimeterOf(kochOutline(n));
      const p1 = perimeterOf(kochOutline(n + 1));
      expect(p1 / p0).toBeCloseTo(expected, 9);
    }
  });

  it('stays inside a bounded circle for n up to 3', () => {
    const bound = (6 / Math.sqrt(3)) * 1.2001;
    for (let n = 0; n <= 3; n++) {
      for (const p of kochOutline(n)) {
        expect(p.length()).toBeLessThanOrEqual(bound);
      }
    }
  });

  it('preserves parent edge endpoints under substitution', () => {
    const parent = kochOutline(1);
    const child = kochOutline(2);
    // spot-check one edge of the parent outline
    const i = 5; // any parent vertex starts an edge; child has 4 segments per parent edge
    const stride = 4;
    expect(child[i * stride].x).toBeCloseTo(parent[i].x, 12);
    expect(child[i * stride].y).toBeCloseTo(parent[i].y, 12);
    expect(child[(i + 1) * stride].x).toBeCloseTo(parent[i + 1].x, 12);
    expect(child[(i + 1) * stride].y).toBeCloseTo(parent[i + 1].y, 12);
  });

  describe('extruded mesh', () => {
    it('has Box3 depth equal to 0.5 within 1e-6', () => {
      const mesh = buildOrnament(2);
      mesh.geometry.computeBoundingBox();
      const box = new Box3().copy(mesh.geometry.boundingBox);
      expect(box.max.z - box.min.z).toBeCloseTo(0.5, 6);
    });

    it('increases vertex count strictly with n', () => {
      let prev = -1;
      for (let n = 0; n <= 3; n++) {
        const mesh = buildOrnament(n);
        const count = mesh.geometry.attributes.position.count;
        expect(count).toBeGreaterThan(prev);
        prev = count;
      }
    });
  });
});
"})
